    value.ir_type == "Boolean"
    value.value == true
} else {
    value.ir_type == "String"
    regex.match(cidr_pattern, value.value)
}

get_key_string(key) = str {
    key.ir_type == "String"
    str := key.value
} else {
    key.ir_type == "VariableReference"
    str := key.value
} else {
    str := ""
}

check_hash_for_binding(hash_node) {
    hash_node.ir_type == "Hash"
    entry := hash_node.value[_]
    key := entry.key
    value := entry.value
    key_str := get_key_string(key)
    regex.match(binding_attributes_pattern, key_str)
    check_binding_value(value)
}

